/* The two numbers the Trial asks for, written as code so that no
   definition is left to memory or to argument. */
typedef struct {
    int arrival;      /* when the job entered the system   */
    int run;          /* how long it needs on the CPU      */
    int first_run;    /* when it first got the CPU         */
    int completion;   /* when its last instruction retired */
} job;

int turnaround(job j) { return j.completion - j.arrival; }
int response(job j)   { return j.first_run  - j.arrival; }

/* Round robin is this loop and nothing more. The timer interrupt is
   what allows run_for to end a slice before the job is done. */
void round_robin(int quantum) {
    while (ready_count() > 0) {
        job *j = ready_dequeue();
        int slice = (j->remaining < quantum) ? j->remaining : quantum;
        run_for(j, slice);
        j->remaining -= slice;
        if (j->remaining > 0)
            ready_enqueue(j);      /* preempted, not finished */
    }
}

#define PAGE_SHIFT  12                    /* 4 KB pages */
#define PAGE_SIZE   (1u << PAGE_SHIFT)
#define OFFSET_MASK (PAGE_SIZE - 1u)
#define PTE_VALID   0x1u

/* A single-level linear page table: one entry per VPN, indexed
   directly, with the frame number above the flag bits. */
unsigned translate(unsigned *pt, unsigned vaddr, int *fault)
{
    unsigned vpn    = vaddr >> PAGE_SHIFT;
    unsigned offset = vaddr & OFFSET_MASK;
    unsigned pte    = pt[vpn];                /* PTBR + vpn * 4 */

    if (!(pte & PTE_VALID)) { *fault = 1; return 0; }

    unsigned pfn = pte >> PAGE_SHIFT;
    *fault = 0;
    return (pfn << PAGE_SHIFT) | offset;
}

#define MAX 8
int buf[MAX], fill = 0, use = 0, count = 0;
pthread_mutex_t m      = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t  empty  = PTHREAD_COND_INITIALIZER;   /* room to put      */
pthread_cond_t  filled = PTHREAD_COND_INITIALIZER;   /* something to get */

void put(int v)
{
    pthread_mutex_lock(&m);
    while (count == MAX)                    /* while, never if */
        pthread_cond_wait(&empty, &m);
    buf[fill] = v; fill = (fill + 1) % MAX; count++;
    pthread_cond_signal(&filled);           /* wake a consumer */
    pthread_mutex_unlock(&m);
}

int get(void)
{
    pthread_mutex_lock(&m);
    while (count == 0)
        pthread_cond_wait(&filled, &m);
    int v = buf[use]; use = (use + 1) % MAX; count--;
    pthread_cond_signal(&empty);            /* wake a producer */
    pthread_mutex_unlock(&m);
    return v;
}

